Here's how to save/restore draft text using MAUI's app lifecycle events and `Preferences`:

**In your `App.xaml.cs`:**

```csharp
public partial class App : Application
{
    public App()
    {
        InitializeComponent();
        MainPage = new NavigationPage(new NotePage());
    }

    protected override Window CreateWindow(IActivationState activationState)
    {
        var window = base.CreateWindow(activationState);

        window.Deactivated += (s, e) =>
        {
            // Fires when app goes to background
            MessagingCenter.Send<App>(this, "SaveDraft");
        };

        window.Activated += (s, e) =>
        {
            // Fires when app returns to foreground
            MessagingCenter.Send<App>(this, "RestoreDraft");
        };

        return window;
    }
}
```

**In your `NotePage.xaml.cs`:**

```csharp
public partial class NotePage : ContentPage
{
    private const string DraftKey = "NoteDraft";

    public NotePage()
    {
        InitializeComponent();

        MessagingCenter.Subscribe<App>(this, "SaveDraft", (sender) =>
        {
            Preferences.Set(DraftKey, NoteEditor.Text ?? string.Empty);
        });

        MessagingCenter.Subscribe<App>(this, "RestoreDraft", (sender) =>
        {
            // Only restore if there's a saved draft
            if (Preferences.ContainsKey(DraftKey))
                NoteEditor.Text = Preferences.Get(DraftKey, string.Empty);
        });

        // Restore on initial load too
        if (Preferences.ContainsKey(DraftKey))
            NoteEditor.Text = Preferences.Get(DraftKey, string.Empty);
    }

    // Clear draft when user explicitly saves
    private void OnSaveClicked(object sender, EventArgs e)
    {
        // ... your save logic ...
        Preferences.Remove(DraftKey);
    }

    protected override void OnDisappearing()
    {
        base.OnDisappearing();
        MessagingCenter.Unsubscribe<App>(this, "SaveDraft");
        MessagingCenter.Unsubscribe<App>(this, "RestoreDraft");
    }
}
```

**Key points:**

- **`Window.Deactivated`** — triggered when backgrounded; persist the text via `Preferences`.
- **`Window.Activated`** — triggered on resume; reload the draft.
- **`Preferences`** — lightweight key-value store that survives app restarts. For large text, use `SecureStorage` or a file instead.
- Clear the draft when the user intentionally saves to avoid stale data.

> **Note:** `MessagingCenter` is deprecated in .NET 8+. If targeting .NET 8+, use the `WeakReferenceMessenger` from the CommunityToolkit.Mvvm package instead.
